import axios from 'axios';

// Em ambiente de desenvolvimento local, usa localhost. 
// No preview do Manus, usamos a URL exposta.
const baseURL = window.location.hostname.includes('manus.computer') 
  ? `https://3001-${window.location.hostname.split('-')[1]}-${window.location.hostname.split('-')[2]}.us1.manus.computer/`
  : 'http://localhost:3001/';

export const inAxios = axios.create({ baseURL });
